324	# Secrets - SlackChannelSecret
325	resource "aws_secretsmanager_secret" "SlackChannelID" {
326	    count = "${var.SlackWebhookURL == "" ? 0 : 1}"
327	    name             = "SlackChannelID"
328	    description      = "Slack Channel ID Secret"
329	    recovery_window_in_days      = 0
330	    tags             = {
331	        "HealthCheckSlack" = "ChannelID"
332	    }
333	    dynamic "replica" {
334	      for_each = var.aha_secondary_region == "" ? [] : [1]
335	      content {
336	        region = var.aha_secondary_region
