339	}
340	resource "aws_secretsmanager_secret_version" "SlackChannelID" {
341	    count = "${var.SlackWebhookURL == "" ? 0 : 1}"
342	    secret_id     = "${aws_secretsmanager_secret.SlackChannelID.*.id[count.index]}"
343	    secret_string = "${var.SlackWebhookURL}"
